    graph: Graph;
    paths: Bug[] | undefined;
    rules: Verdict[];
    properties: Property[];
    stop: Stop | undefined;
    drawing: { status: number | null } | undefined;
    states: { distinct: number; initial: number; complete: boolean; cut: boolean };
  },
  found: Bug[],
  chart: Chart | undefined,
  stories: Map<Bug, Story>,
