    mark(graph, readMarks(readMessages(out), "chart"), spec.variables, stateRules(spec)).size,
    0,
  );
  const bad: Value[][] = [];
  for (const s of graph.states.values())
    if (s.breaks.length)
      bad.push([field(s.vars.rmState, "r1"), field(s.vars.rmState, "r2")].sort());
  assert.deepEqual(bad, [
    ["aborted", "committed"],
    ["aborted", "committed"],
