  for (const mode of ["div", "assert"]) {
    const v = agrees("Late", { Late: late }, lateCfg(mode, "Small"));
    assert.equal(v.status, 1);
    assert.deepEqual(v.breaks, new Map([["Small", 1]]));
    assert.deepEqual(v.unchecked, ["NoDeadlock"]);
