--- file: scripts/test/corpus/PickWorker/PickWorker.cfg ---
CONSTANTS Workers = {w1, w2}
CONSTANTS First = w1
SPECIFICATION Spec
PROPERTY PicksFirst
SYMMETRY Perms
CHECK_DEADLOCK FALSE


--- file: scripts/test/corpus/PickWorker/PickWorker.tla ---
---- MODULE PickWorker ----
EXTENDS TLC
CONSTANTS Workers, First
VARIABLE picked
Init == picked = {}
Pick(w) == picked = {} /\ picked' = {w}
Next == \E w \in Workers : Pick(w)
Spec == Init /\ [][Next]_picked /\ WF_picked(Next)
Perms == Permutations(Workers)
PicksFirst == <>(First \in picked)
====


