--- file: scripts/test/corpus/Shadow/Shadow.cfg ---
SPECIFICATION Spec
CONSTANT Hold = TRUE
PROPERTY Shadow Shade Hold
CHECK_DEADLOCK FALSE


--- file: scripts/test/corpus/Shadow/Shadow.tla ---
---- MODULE Shadow ----
EXTENDS Naturals, ShadowLib
CONSTANT Hold
VARIABLE x
vars == <<x>>
Init == x = 0
Next == x < 3 /\ x' = x + 1
Spec == Init /\ [][Next]_vars /\ WF_vars(Next)
Shadow == <>(x = 3)
Shade == x \in 0..1
====


--- file: scripts/test/corpus/Shadow/ShadowLib.tla ---
---- MODULE ShadowLib ----
LOCAL Shadow == TRUE
LOCAL Shade == [](TRUE)
LOCAL I == INSTANCE ShadowSub WITH c <- Shadow
USE DEF Shadow, Shade
====


--- file: scripts/test/corpus/Shadow/ShadowSub.tla ---
---- MODULE ShadowSub ----
CONSTANT c
====


