--- file: scripts/test/corpus/TwoPhaseFixed/TwoPhaseFixed.cfg ---
CONSTANT RM = {r1, r2}
SPECIFICATION TPSpec
INVARIANT TPTypeOK TCConsistent


--- file: scripts/test/corpus/TwoPhaseFixed/TwoPhaseFixed.tla ---
---- MODULE TwoPhaseFixed ----
\* Lamport's two-phase commit: the transaction manager commits only when every
\* resource manager has prepared.
CONSTANT RM

VARIABLES rmState, tmState, tmPrepared, msgs
vars == <<rmState, tmState, tmPrepared, msgs>>

Messages == [type : {"Prepared"}, rm : RM] \cup [type : {"Commit", "Abort"}]

TPTypeOK ==
  /\ rmState \in [RM -> {"working", "prepared", "committed", "aborted"}]
  /\ tmState \in {"init", "done"}
  /\ tmPrepared \subseteq RM
  /\ msgs \subseteq Messages

TPInit ==
  /\ rmState = [r \in RM |-> "working"]
  /\ tmState = "init"
  /\ tmPrepared = {}
  /\ msgs = {}

TMRcvPrepared(r) ==
  /\ tmState = "init"
  /\ [type |-> "Prepared", rm |-> r] \in msgs
  /\ tmPrepared' = tmPrepared \cup {r}
  /\ UNCHANGED <<rmState, tmState, msgs>>

TMCommit ==
  /\ tmState = "init"
  /\ tmPrepared = RM
  /\ tmState' = "done"
  /\ msgs' = msgs \cup {[type |-> "Commit"]}
  /\ UNCHANGED <<rmState, tmPrepared>>

TMAbort ==
  /\ tmState = "init"
  /\ tmState' = "done"
  /\ msgs' = msgs \cup {[type |-> "Abort"]}
  /\ UNCHANGED <<rmState, tmPrepared>>

RMPrepare(r) ==
  /\ rmState[r] = "working"
  /\ rmState' = [rmState EXCEPT ![r] = "prepared"]
  /\ msgs' = msgs \cup {[type |-> "Prepared", rm |-> r]}
  /\ UNCHANGED <<tmState, tmPrepared>>

RMChooseToAbort(r) ==
  /\ rmState[r] = "working"
  /\ rmState' = [rmState EXCEPT ![r] = "aborted"]
  /\ UNCHANGED <<tmState, tmPrepared, msgs>>

RMRcvCommitMsg(r) ==
  /\ [type |-> "Commit"] \in msgs
  /\ rmState' = [rmState EXCEPT ![r] = "committed"]
  /\ UNCHANGED <<tmState, tmPrepared, msgs>>

RMRcvAbortMsg(r) ==
  /\ [type |-> "Abort"] \in msgs
  /\ rmState' = [rmState EXCEPT ![r] = "aborted"]
  /\ UNCHANGED <<tmState, tmPrepared, msgs>>

TPNext ==
  \/ TMCommit \/ TMAbort
  \/ \E r \in RM :
       TMRcvPrepared(r) \/ RMPrepare(r) \/ RMChooseToAbort(r)
         \/ RMRcvCommitMsg(r) \/ RMRcvAbortMsg(r)

TPSpec == TPInit /\ [][TPNext]_vars

\* No resource manager commits while another aborts.
TCConsistent ==
  \A r1, r2 \in RM : ~ /\ rmState[r1] = "aborted"
                       /\ rmState[r2] = "committed"
====


--- file: scripts/test/corpus/TwoPhaseFixed/chart.mmd ---
stateDiagram-v2
  direction LR
  state "At the same time" as all {
    state "Manager" as r0 {
      s0: init
      s1: done
      [*] --> s0
      s0 --> s1: TMAbort
      s0 --> s1: TMCommit [when r1 is prepared and r2 is prepared]
    }
    --
    state "r1" as r1 {
      s2: working
      s3: prepared
      s4: aborted
      s5: committed
      [*] --> s2
      s2 --> s3: RMPrepare
      s2 --> s4: RMChooseToAbort
      s2 --> s4: RMRcvAbortMsg [when Manager is done]
      s3 --> s4: RMRcvAbortMsg [when Manager is done and r2 is not committed]
      s3 --> s5: RMRcvCommitMsg [when Manager is done and r2 is one of committed, prepared]
    }
    --
    state "r2" as r2 {
      s6: working
      s7: prepared
      s8: aborted
      s9: committed
      [*] --> s6
      s6 --> s7: RMPrepare
      s6 --> s8: RMChooseToAbort
      s6 --> s8: RMRcvAbortMsg [when Manager is done]
      s7 --> s8: RMRcvAbortMsg [when Manager is done and r1 is not committed]
      s7 --> s9: RMRcvCommitMsg [when Manager is done and r1 is one of committed, prepared]
    }
  }


